async function fetchSubgraphData(subgraph, query, variables) {
  try {
    const data = await fetchFromSubgraph(subgraph, {
      query,
      variables,
      requestId: "useAbstractTransactions"
    });
    return data;
  } catch (error) {
    console.error("Failed to fetch from subgraph:", error);
    return {};
  }
}
function transformV2Transaction(tx, type) {
  let token0Quantity;
  let token1Quantity;
  let account;
  if (type === TransactionType.SWAP) {
    token0Quantity = tx.amount0In !== "0" ? tx.amount0In : `-${tx.amount0Out}`;
    token1Quantity = tx.amount1In !== "0" ? tx.amount1In : `-${tx.amount1Out}`;
    account = tx.sender;
  } else {
    token0Quantity = type === TransactionType.ADD ? tx.amount0 : `-${tx.amount0}`;
    token1Quantity = type === TransactionType.ADD ? tx.amount1 : `-${tx.amount1}`;
    account = tx.to || tx.sender || "unknown";
  }
  const chain = Chain.AbstractTestnet;
  const toGqlToken = (t) => ({
    address: t.id,
    chain,
    decimals: Number(t.decimals ?? "18"),
    name: t.name,
    project: { logo: { url: getTokenLogoUrl(t.id) ?? "" } },
    symbol: t.symbol
  });
  return {
    id: tx.id,
    type,
    // Keep the original TransactionType (string values: 'Swap', 'Add', 'Remove')
    timestamp: tx.timestamp,
    hash: tx.transaction.id,
    blockNumber: tx.transaction.blockNumber,
    account,
    token0: toGqlToken(tx.pair.token0),
    token1: toGqlToken(tx.pair.token1),
    token0Quantity,
    token1Quantity,
    usdValue: {
      value: parseFloat(tx.amountUSD || "0")
    }
  };
}
function transformV3Transaction(tx, type) {
  let token0Quantity;
  let token1Quantity;
  let account;
  if (type === TransactionType.SWAP) {
    token0Quantity = tx.amount0;
    token1Quantity = tx.amount1;
    account = tx.sender;
  } else {
    token0Quantity = type === TransactionType.ADD ? tx.amount0 : `-${tx.amount0}`;
    token1Quantity = type === TransactionType.ADD ? tx.amount1 : `-${tx.amount1}`;
    account = tx.owner || tx.sender;
  }
  const chain = Chain.AbstractTestnet;
  const toGqlToken = (t) => ({
    address: t.id,
    chain,
    decimals: Number(t.decimals ?? "18"),
    name: t.name,
    project: { logo: { url: getTokenLogoUrl(t.id) ?? "" } },
    symbol: t.symbol
  });
  return {
    id: tx.id,
    type,
    // Keep the original TransactionType (string values: 'Swap', 'Add', 'Remove')
    timestamp: tx.timestamp,
    hash: tx.transaction.id,
    blockNumber: tx.transaction.blockNumber,
    account,
    token0: toGqlToken(tx.pool.token0),
    token1: toGqlToken(tx.pool.token1),
    token0Quantity,
    token1Quantity,
    usdValue: {
      value: parseFloat(tx.amountUSD || "0")
    }
  };
}
export function useAbstractTransactions(chainId, filter = [TransactionType.SWAP, TransactionType.ADD, TransactionType.REMOVE], pageSize = 20) {
  return useQuery({
    queryKey: ["abstract-transactions", chainId, filter, pageSize],
    queryFn: async () => {
      const subgraphs = getAbstractSubgraphs(UniverseChainId.Mainnet);
      const allTransactions = [];
      const queries = [];
      if (filter.includes(TransactionType.SWAP)) {
        queries.push(
          fetchSubgraphData(subgraphs.v2, V2_TRANSACTIONS_QUERY, { first: pageSize, skip: 0 }),
          fetchSubgraphData(subgraphs.v3, V3_SWAPS_QUERY, { first: pageSize, skip: 0 })
        );
      }
      if (filter.includes(TransactionType.ADD)) {
        queries.push(
          fetchSubgraphData(subgraphs.v2, V2_MINTS_QUERY, { first: pageSize, skip: 0 }),
          fetchSubgraphData(subgraphs.v3, V3_MINTS_QUERY, { first: pageSize, skip: 0 })
        );
      }
      if (filter.includes(TransactionType.REMOVE)) {
        queries.push(
          fetchSubgraphData(subgraphs.v2, V2_BURNS_QUERY, { first: pageSize, skip: 0 }),
          fetchSubgraphData(subgraphs.v3, V3_BURNS_QUERY, { first: pageSize, skip: 0 })
        );
      }
      const results = await Promise.all(queries);
      let resultIndex = 0;
      if (filter.includes(TransactionType.SWAP)) {
        const v2Swaps = results[resultIndex++]?.swaps || [];
        const v3Swaps = results[resultIndex++]?.swaps || [];
        allTransactions.push(
          ...v2Swaps.map((tx) => transformV2Transaction(tx, TransactionType.SWAP)),
          ...v3Swaps.map((tx) => transformV3Transaction(tx, TransactionType.SWAP))
        );
      }
      if (filter.includes(TransactionType.ADD)) {
        const v2Mints = results[resultIndex++]?.mints || [];
        const v3Mints = results[resultIndex++]?.mints || [];
        allTransactions.push(
          ...v2Mints.map((tx) => transformV2Transaction(tx, TransactionType.ADD)),
          ...v3Mints.map((tx) => transformV3Transaction(tx, TransactionType.ADD))
        );
      }
      if (filter.includes(TransactionType.REMOVE)) {
        const v2Burns = results[resultIndex++]?.burns || [];
        const v3Burns = results[resultIndex++]?.burns || [];
        allTransactions.push(
          ...v2Burns.map((tx) => transformV2Transaction(tx, TransactionType.REMOVE)),
          ...v3Burns.map((tx) => transformV3Transaction(tx, TransactionType.REMOVE))
        );
      }
      return allTransactions.sort((a, b) => parseInt(b.timestamp) - parseInt(a.timestamp));
    },
    enabled: !!chainId,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    staleTime: 15e3
    // Consider data stale after 15 seconds
  });
}
export function useAllAbstractTransactions(chainId, filter = [TransactionType.SWAP, TransactionType.ADD, TransactionType.REMOVE]) {
  const { data: transactions = [], isLoading, error } = useAbstractTransactions(chainId, filter);
  const loadMore = useMemo(() => {
    return ({ onComplete }) => {
      onComplete?.();
    };
  }, []);
  return {
    transactions,
    loading: isLoading,
    errorV2: error,
    errorV3: error,
    errorV4: null,
    loadMore
  };
}
export function useAbstractPoolTransactionsInfinite(poolAddress, chainId, filter = [TransactionType.SWAP, TransactionType.ADD, TransactionType.REMOVE], pageSize = 50) {
  return useInfiniteQuery({
    queryKey: ["abstract-pool-transactions", poolAddress.toLowerCase(), chainId, filter, pageSize],
    queryFn: async ({ pageParam }) => {
      const subgraphs = getAbstractSubgraphs(chainId);
      const txs = [];
      const cursor = pageParam;
      const v2Vars = { first: pageSize, skip: 0, pool: poolAddress.toLowerCase(), cursor };
      const v3Vars = { first: pageSize, skip: 0, pool: poolAddress.toLowerCase(), cursor };
      const whereV2 = cursor ? "pair: $pool, timestamp_lt: $cursor" : "pair: $pool";
      const whereV3 = cursor ? "pool: $pool, timestamp_lt: $cursor" : "pool: $pool";
      const V2_POOL_SWAPS = `
        query($first: Int!, $skip: Int!, $pool: String!, $cursor: BigInt) {
          swaps(first: $first, skip: $skip, orderBy: timestamp, orderDirection: desc, where: { ${whereV2} }) {
            id timestamp transaction { id blockNumber } sender to amount0In amount1In amount0Out amount1Out amountUSD
            pair { id token0 { id symbol name decimals } token1 { id symbol name decimals } }
          }
        }
      `;
      const V2_POOL_MINTS = `
        query($first: Int!, $skip: Int!, $pool: String!, $cursor: BigInt) {
          mints(first: $first, skip: $skip, orderBy: timestamp, orderDirection: desc, where: { ${whereV2} }) {
            id timestamp transaction { id blockNumber } to sender amount0 amount1 amountUSD
            pair { id token0 { id symbol name decimals } token1 { id symbol name decimals } }
          }
        }
      `;
      const V2_POOL_BURNS = `
        query($first: Int!, $skip: Int!, $pool: String!, $cursor: BigInt) {
          burns(first: $first, skip: $skip, orderBy: timestamp, orderDirection: desc, where: { ${whereV2} }) {
            id timestamp transaction { id blockNumber } to amount0 amount1 amountUSD
            pair { id token0 { id symbol name decimals } token1 { id symbol name decimals } }
          }
        }
      `;
      const V3_POOL_SWAPS = `
        query($first: Int!, $skip: Int!, $pool: String!, $cursor: BigInt) {
          swaps(first: $first, skip: $skip, orderBy: timestamp, orderDirection: desc, where: { ${whereV3} }) {
            id timestamp transaction { id blockNumber } sender recipient amount0 amount1 amountUSD
            pool { id token0 { id symbol name decimals } token1 { id symbol name decimals } }
          }
        }
      `;
      const V3_POOL_MINTS = `
        query($first: Int!, $skip: Int!, $pool: String!, $cursor: BigInt) {
          mints(first: $first, skip: $skip, orderBy: timestamp, orderDirection: desc, where: { ${whereV3} }) {
            id timestamp transaction { id blockNumber } sender owner amount0 amount1 amountUSD
            pool { id token0 { id symbol name decimals } token1 { id symbol name decimals } }
          }
        }
      `;
      const V3_POOL_BURNS = `
        query($first: Int!, $skip: Int!, $pool: String!, $cursor: BigInt) {
          burns(first: $first, skip: $skip, orderBy: timestamp, orderDirection: desc, where: { ${whereV3} }) {
            id timestamp transaction { id blockNumber } owner amount0 amount1 amountUSD
            pool { id token0 { id symbol name decimals } token1 { id symbol name decimals } }
          }
        }
      `;
      const promises = [];
      if (filter.includes(TransactionType.SWAP)) {
        promises.push(fetchSubgraphData(subgraphs.v2, V2_POOL_SWAPS, v2Vars));
        promises.push(fetchSubgraphData(subgraphs.v3, V3_POOL_SWAPS, v3Vars));
      }
      if (filter.includes(TransactionType.ADD)) {
        promises.push(fetchSubgraphData(subgraphs.v2, V2_POOL_MINTS, v2Vars));
        promises.push(fetchSubgraphData(subgraphs.v3, V3_POOL_MINTS, v3Vars));
      }
      if (filter.includes(TransactionType.REMOVE)) {
        promises.push(fetchSubgraphData(subgraphs.v2, V2_POOL_BURNS, v2Vars));
        promises.push(fetchSubgraphData(subgraphs.v3, V3_POOL_BURNS, v3Vars));
      }
      const results = await Promise.all(promises);
      let idx = 0;
      if (filter.includes(TransactionType.SWAP)) {
        const v2 = results[idx++]?.swaps ?? [];
        const v3 = results[idx++]?.swaps ?? [];
        txs.push(...v2.map((r) => transformV2Transaction(r, TransactionType.SWAP)));
        txs.push(...v3.map((r) => transformV3Transaction(r, TransactionType.SWAP)));
      }
      if (filter.includes(TransactionType.ADD)) {
        const v2 = results[idx++]?.mints ?? [];
        const v3 = results[idx++]?.mints ?? [];
        txs.push(...v2.map((r) => transformV2Transaction(r, TransactionType.ADD)));
        txs.push(...v3.map((r) => transformV3Transaction(r, TransactionType.ADD)));
      }
      if (filter.includes(TransactionType.REMOVE)) {
        const v2 = results[idx++]?.burns ?? [];
        const v3 = results[idx++]?.burns ?? [];
        txs.push(...v2.map((r) => transformV2Transaction(r, TransactionType.REMOVE)));
        txs.push(...v3.map((r) => transformV3Transaction(r, TransactionType.REMOVE)));
      }
      const sorted = txs.sort((a, b) => parseInt(b.timestamp) - parseInt(a.timestamp));
      const nextCursor = sorted.length ? parseInt(sorted[sorted.length - 1].timestamp) : void 0;
      return { items: sorted, nextCursor };
    },
    getNextPageParam: (lastPage) => lastPage.nextCursor,
    enabled: Boolean(poolAddress && chainId),
    refetchInterval: 3e4,
    staleTime: 15e3
  });
}
